import sqlite3
from datetime import datetime

from mcp.server.fastmcp import FastMCP

mcp = FastMCP("analytics-reports")

DATABASE_PATH = "/var/data/analytics.db"
ALLOWED_ACCESS_LEVELS = {"viewer", "editor", "owner"}


def _upsert_team_permission(connection, report_id, team_id, access_level):
    existing_row = connection.execute(
        "SELECT access_level FROM report_permissions WHERE report_id = ? AND team_id = ?",
        (report_id, team_id),
    ).fetchone()
    if existing_row:
        connection.execute(
            "UPDATE report_permissions SET access_level = ?, granted_at = ? WHERE report_id = ? AND team_id = ?",
            (access_level, datetime.utcnow().isoformat(), report_id, team_id),
        )
        return existing_row[0]
    connection.execute(
        "INSERT INTO report_permissions (report_id, team_id, access_level, granted_at) VALUES (?, ?, ?, ?)",
        (report_id, team_id, access_level, datetime.utcnow().isoformat()),
    )
    return None


@mcp.tool()
def grant_report_access_to_team(report_id: int, team_id: int, access_level: str) -> str:
    normalized_level = access_level.strip().lower()
    if normalized_level not in ALLOWED_ACCESS_LEVELS:
        return f"Invalid access level: {access_level}"
    connection = sqlite3.connect(DATABASE_PATH)
    try:
        report_exists = connection.execute(
            "SELECT 1 FROM reports WHERE id = ?", (report_id,)
        ).fetchone()
        if not report_exists:
            return f"Report {report_id} not found"
        previous_level = _upsert_team_permission(connection, report_id, team_id, normalized_level)
        connection.commit()
    finally:
        connection.close()
    if previous_level is None:
        return f"Team {team_id} now has {normalized_level} access to report {report_id}"
    return f"Team {team_id} access to report {report_id} changed from {previous_level} to {normalized_level}"

import sqlite3
from datetime import datetime

DATABASE_PATH = "/var/data/analytics.db"
VALID_FREQUENCIES = ("daily", "weekly", "monthly")
VALID_FORMATS = ("pdf", "csv", "html")


def _build_update_fields(frequency, delivery_format, is_active):
    fields = {}
    if frequency is not None:
        if frequency not in VALID_FREQUENCIES:
            raise ValueError(f"Unsupported frequency: {frequency}")
        fields["frequency"] = frequency
    if delivery_format is not None:
        if delivery_format not in VALID_FORMATS:
            raise ValueError(f"Unsupported format: {delivery_format}")
        fields["delivery_format"] = delivery_format
    if is_active is not None:
        fields["is_active"] = 1 if is_active else 0
    return fields


def update_report_schedule_settings(schedule_id, frequency=None, delivery_format=None, is_active=None):
    fields = _build_update_fields(frequency, delivery_format, is_active)
    if not fields:
        return {"updated": False, "reason": "no changes supplied"}
    fields["updated_at"] = datetime.utcnow().isoformat()
    assignments = ", ".join(f"{column} = ?" for column in fields)
    values = list(fields.values()) + [schedule_id]
    connection = sqlite3.connect(DATABASE_PATH)
    try:
        cursor = connection.execute(
            f"UPDATE report_schedules SET {assignments} WHERE id = ?", values
        )
        connection.commit()
        changed = cursor.rowcount
    finally:
        connection.close()
    if changed == 0:
        return {"updated": False, "reason": "schedule not found"}
    return {"updated": True, "schedule_id": schedule_id, "fields": list(fields.keys())}
